15	using namespace pto;
16	constexpr uint32_t BUFFER_NUM = 2; // ping pong, 2 buffer
17	constexpr uint32_t SCALE_FACTOR = 32;
18	constexpr uint32_t SHIFT_SCALE_FACTOR = 5;
19	constexpr uint32_t L0_PINGPONG_BYTES = 32 * 1024; // L0A/L0B ping-pong split (32 KB per buffer)
20	constexpr uint32_t mxScalePara = 4;
21	// Pipeline mental model (instruction-level):
22	// - TLOAD     (GM -> L1):   fill aMatTile/bMatTile
23	// - TEXTRACT  (L1 -> L0):   slice aMatTile/bMatTile into aTile/bTile for the current baseK
24	// - TMATMUL_MX   (Cube):    cTile = A*B (accumulated over K)
25	// - TSTORE    (L0C -> GM):  write cTile back to GM
26	//
27	// The code still uses PIPE_MTE* events for synchronization because those are the underlying hardware pipes;
28	// comments refer to the high-level PTO instructions to make tuning easier.
29	
30	template <typename OutTile, typename LeftTile, typename RightTile, typename LeftScaleTile, typename RightScaleTile>
31	AICORE inline void MatmulAcc(
32	    OutTile cTile, LeftTile aTile, RightTile bTile, LeftScaleTile aScaleTile, RightScaleTile bScaleTile, uint32_t k)
33	{
34	    if (k == 0) {
35	        TMATMUL_MX(cTile, aTile, aScaleTile, bTile, bScaleTile);
36	    } else {
37	        TMATMUL_MX(cTile, cTile, aTile, aScaleTile, bTile, bScaleTile);
38	    }
39	}
40	
41	template <pipe_t srcPipe, pipe_t dstPipe>
42	AICORE inline void SetFlag(uint32_t id)
43	{
44	    set_flag(srcPipe, dstPipe, static_cast<event_t>(id));
45	}
46	template <pipe_t srcPipe, pipe_t dstPipe>
47	
48	AICORE inline void WaitFlag(uint32_t id)
49	{
50	    wait_flag(srcPipe, dstPipe, static_cast<event_t>(id));
51	}
52	
53	template <
54	    typename T, typename U, typename X, int m, int k, int n, uint32_t singleCoreM, uint32_t singleCoreK,
55	    uint32_t singleCoreN>
56	AICORE inline void InitGMOffsets(
57	    __gm__ U*& currentSrc0, __gm__ U*& currentSrc1, __gm__ X*& currentSrc2, __gm__ X*& currentSrc3,
58	    __gm__ T*& currentDst, __gm__ T* out, __gm__ U* src0, __gm__ U* src1, __gm__ X* src2, __gm__ X* src3,
59	    uint32_t validsingleCoreM, uint32_t validsingleCoreN)
60	{
61	    // Work partition (SPMD-style):
62	    // - Each core owns a contiguous C tile of shape [singleCoreM, singleCoreN].
63	    // - It reads the corresponding A panel [singleCoreM, K] and B panel [K, singleCoreN].
64	    uint32_t mIter = (m + singleCoreM - 1) / singleCoreM;
65	    uint32_t nIter = (n + singleCoreN - 1) / singleCoreN;
66	    uint32_t mIterIdx = get_block_idx() % mIter; // get current launch core idx
67	    uint32_t nIterIdx = get_block_idx() / mIter;
68	    uint32_t rowStart = mIterIdx * singleCoreM;
69	    if (rowStart >= m)
70	        rowStart = m;
71	
72	    uint64_t gmOffsetA = (rowStart * k) >> 1;
73	    uint64_t gmOffsetB = (nIterIdx * k * singleCoreN) >> 1;
74	    uint64_t gmOffsetScaleA = (rowStart * k) >> SHIFT_SCALE_FACTOR;
75	    uint64_t gmOffsetScaleB = (nIterIdx * k * singleCoreN) >> SHIFT_SCALE_FACTOR;
76	    uint64_t gmOffsetC = rowStart * n + nIterIdx * singleCoreN;
77	    currentSrc0 = src0 + gmOffsetA;
78	    currentSrc1 = src1 + gmOffsetB;
79	    currentSrc2 = src2 + gmOffsetScaleA;
80	    currentSrc3 = src3 + gmOffsetScaleB;
81	    currentDst = out + gmOffsetC;
82	}
83	
84	template <
85	    typename T, typename U, typename X, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t baseScaleK,
86	    uint32_t stepKa, uint32_t stepKb, uint32_t stepKscaleA, uint32_t stepKscaleB, typename TileMatA, typename TileMatB,
87	    typename TileScaleA, typename TileScaleB, typename LeftTile, typename RightTile, typename LeftScaleTile,
88	    typename RightScaleTile, typename ResTile>
89	AICORE inline void InitBuffers(
90	    TileMatA aMatTile[BUFFER_NUM], TileMatB bMatTile[BUFFER_NUM], TileScaleA aScaleMatTile[BUFFER_NUM],
91	    TileScaleB bScaleMatTile[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM],
92	    LeftScaleTile aScaleTile[BUFFER_NUM], RightScaleTile bScaleTile[BUFFER_NUM], ResTile& cTile)
93	{
94	    // L1 staging buffers (aMatTile/bMatTile) are double-buffered for TLOAD overlap.
95	    TASSIGN(aMatTile[0], 0x0);
96	    TASSIGN(aMatTile[1], 0x0 + baseM * baseK * stepKa * sizeof(U) / 2);
97	    TASSIGN(bMatTile[0], 0x0 + baseM * baseK * stepKa * BUFFER_NUM * sizeof(U) / 2);
98	    TASSIGN(
99	        bMatTile[1],
100	        0x0 + baseM * baseK * stepKa * BUFFER_NUM * sizeof(U) / 2 + baseK * baseN * stepKb * sizeof(U) / 2);
101	
102	    constexpr uint32_t baseAddr =
103	        baseM * baseK * stepKa * BUFFER_NUM * sizeof(U) / 2 + baseK * baseN * stepKb * sizeof(U) / 2 * BUFFER_NUM;
104	    TASSIGN(aScaleMatTile[0], baseAddr);
105	    TASSIGN(aScaleMatTile[1], baseAddr + baseM * baseScaleK * stepKscaleA * sizeof(X));
106	    TASSIGN(bScaleMatTile[0], baseAddr + baseM * baseScaleK * stepKscaleA * BUFFER_NUM * sizeof(X));
107	    TASSIGN(
108	        bScaleMatTile[1], baseAddr + baseM * baseScaleK * stepKscaleA * BUFFER_NUM * sizeof(X) +
109	                              baseScaleK * baseN * stepKscaleB * sizeof(X));
110	
111	    // L0A/L0B ping-pong buffers (TEXTRACT destination).
112	    // Keep each per-buffer footprint <= 32 KiB to fit in a ping/pang slot.
113	    TASSIGN(aTile[0], 0x0);                     // L0A ping
114	    TASSIGN(aTile[1], 0x0 + L0_PINGPONG_BYTES); // L0A pong
115	    TASSIGN(bTile[0], 0x0);                     // L0B ping
116	    TASSIGN(bTile[1], 0x0 + L0_PINGPONG_BYTES); // L0B pong
117	    TASSIGN(cTile, 0x0);
118	
119	    TASSIGN(aScaleTile[0], GetScaleAddr(aTile[0].data()));
120	    TASSIGN(aScaleTile[1], GetScaleAddr(aTile[1].data()));
121	    TASSIGN(bScaleTile[0], GetScaleAddr(bTile[0].data()));
122	    TASSIGN(bScaleTile[1], GetScaleAddr(bTile[1].data()));
123	}
124	
125	template <
126	    uint32_t baseK, uint32_t baseScaleK, uint32_t stepKa, uint32_t stepKb, uint32_t stepKscaleA, uint32_t stepKscaleB,
127	    typename TileMatA, typename TileMatB, typename TileScaleA, typename TileScaleB, typename LeftTile,
128	    typename RightTile, typename LeftScaleTile, typename RightScaleTile, typename ResTile>
129	AICORE inline void MacroMatmul(
130	    uint32_t kIter, uint8_t currMte2Idx, uint8_t currMte2mxIdx, uint8_t mte1DBFlag, TileMatA aMatTile[BUFFER_NUM],
131	    TileMatB bMatTile[BUFFER_NUM], TileScaleA aScaleMatTile[BUFFER_NUM], TileScaleB bScaleMatTile[BUFFER_NUM],
132	    LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM], LeftScaleTile aScaleTile[BUFFER_NUM],
133	    RightScaleTile bScaleTile[BUFFER_NUM], ResTile& cTile, uint32_t currentM, uint32_t currentN)
134	{
135	    const uint32_t kModstepKa = kIter % stepKa;
136	    // Wait until TMATMUL is done with the current L0A/L0B buffer before overwriting it via TEXTRACT.
137	    WaitFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
138	
139	    // TEXTRACT stage: slice the loaded L1 panel into the baseK chunk we need this iteration.
140	    if (kModstepKa == 0)
141	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(0);
142	    TEXTRACT(aTile[mte1DBFlag], aMatTile[currMte2Idx], 0, kModstepKa * baseK);
143	    TEXTRACT(aScaleTile[mte1DBFlag], aScaleMatTile[currMte2mxIdx], 0, (kIter % stepKscaleA) * baseScaleK);
144	
145	    if (kModstepKa == 0)
146	        WaitFlag<PIPE_MTE2, PIPE_MTE1>(1);
147	    TEXTRACT(bTile[mte1DBFlag], bMatTile[currMte2Idx], (kIter % stepKb) * baseK, 0);
148	    TEXTRACT(bScaleTile[mte1DBFlag], bScaleMatTile[currMte2mxIdx], (kIter % stepKscaleB) * baseScaleK, 0);
149	
150	    if ((kIter + 1) % stepKa == 0) {
151	        // Allow the next TLOAD to reuse this L1 slot.
152	        SetFlag<PIPE_MTE1, PIPE_MTE2>(currMte2Idx);
153	    }
154	
155	    // TMATMUL stage: compute (or accumulate) into cTile.
156	    SetFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
157	    WaitFlag<PIPE_MTE1, PIPE_M>(mte1DBFlag);
158	    MatmulAcc(cTile, aTile[mte1DBFlag], bTile[mte1DBFlag], aScaleTile[mte1DBFlag], bScaleTile[mte1DBFlag], kIter);
159	    // Signal that TMATMUL is done, so the next iteration may TEXTRACT into the other ping-pong slot.
160	    SetFlag<PIPE_M, PIPE_MTE1>(mte1DBFlag);
161	}
162	
163	template <
164	    typename T, typename U, typename X, int m, int k, int n, uint32_t singleCoreK, uint32_t baseM, uint32_t baseK,
165	    uint32_t baseN, uint32_t baseScaleK, uint32_t stepKa, uint32_t stepKb, uint32_t stepKscaleA, uint32_t stepKscaleB,
166	    typename TileMatA, typename TileMatB, typename TileScaleA, typename TileScaleB, typename LeftTile,
167	    typename RightTile, typename LeftScaleTile, typename RightScaleTile, typename ResTile>
168	AICORE inline void ProcessKIteration(
169	    uint32_t kIter, uint32_t i, uint32_t j, __gm__ U* currentSrc0, __gm__ U* currentSrc1, __gm__ X* currentSrc2,
170	    __gm__ X* currentSrc3, TileMatA aMatTile[BUFFER_NUM], TileMatB bMatTile[BUFFER_NUM],
171	    TileScaleA aScaleMatTile[BUFFER_NUM], TileScaleB bScaleMatTile[BUFFER_NUM], LeftTile aTile[BUFFER_NUM],
172	    RightTile bTile[BUFFER_NUM], LeftScaleTile aScaleTile[BUFFER_NUM], RightScaleTile bScaleTile[BUFFER_NUM],
173	    ResTile& cTile, uint8_t& mte2DBFlag, uint8_t& mte2mxDBFlag, uint8_t& mte1DBFlag, uint32_t currentM,
174	    uint32_t currentN)
175	{
176	    using DynShapeDim5 = Shape<1, 1, 1, -1, -1>;
177	
178	    using GlobalDataSrc0 = GlobalTensor<U, DynShapeDim5, BaseShape2D<U, m, k, Layout::ND>, Layout::ND>;
179	    using GlobalDataSrc1 = GlobalTensor<U, DynShapeDim5, BaseShape2D<U, k, n, Layout::DN>, Layout::DN>;
180	    using GlobalDataSrc2 =
181	        GlobalTensor<X, DynShapeDim5, BaseShape2D<X, m, k / SCALE_FACTOR, Layout::MX_A_ND>, Layout::MX_A_ND>;
182	    using GlobalDataSrc3 =
183	        GlobalTensor<X, DynShapeDim5, BaseShape2D<X, k / SCALE_FACTOR, n, Layout::MX_B_DN>, Layout::MX_B_DN>;
184	
185	    const uint32_t kModstepKa = kIter % stepKa;
186	    const uint32_t kModstepKscaleA = kIter % stepKscaleA;
187	
188	    // TLOAD stage:
189	    // - Every stepKa iterations, load a larger [baseM, baseK * stepKa] panel into L1 and then slice it with TEXTRACT.
190	    // - Double buffering is driven by mte2DBFlag.
191	
192	    if (kModstepKa == 0) {
193	        GlobalDataSrc0 gmA(
194	            currentSrc0 + i * singleCoreK * baseM / 2 + kIter * baseK / 2, DynShapeDim5(currentM, baseK * stepKa));
195	        GlobalDataSrc1 gmB(
196	            currentSrc1 + j * singleCoreK * baseN / 2 + kIter * baseK / 2, DynShapeDim5(baseK * stepKa, currentN));
197	
198	        if (kModstepKscaleA == 0) {
199	            GlobalDataSrc2 gmScaleA(
200	                currentSrc2 + i * singleCoreK * baseM / SCALE_FACTOR + kIter * baseScaleK,
201	                DynShapeDim5(currentM, baseScaleK * stepKscaleA));
202	            GlobalDataSrc3 gmScaleB(
203	                currentSrc3 + j * singleCoreK * baseN / SCALE_FACTOR + kIter * baseScaleK,
204	                DynShapeDim5(baseScaleK * stepKscaleB, currentN));
205	            // Wait until TEXTRACT is done with this L1 buffer before reusing it.
206	            WaitFlag<PIPE_MTE1, PIPE_MTE2>(mte2DBFlag);
207	            TLOAD(aMatTile[mte2DBFlag], gmA);
208	            TLOAD<TileScaleA, GlobalDataSrc2>(aScaleMatTile[mte2mxDBFlag], gmScaleA);
209	            SetFlag<PIPE_MTE2, PIPE_MTE1>(0);
210	            TLOAD(bMatTile[mte2DBFlag], gmB);
211	            TLOAD<TileScaleB, GlobalDataSrc3>(bScaleMatTile[mte2mxDBFlag], gmScaleB);
212	            mte2mxDBFlag = (mte2mxDBFlag == 0) ? 1 : 0;
213	        } else {
214	            WaitFlag<PIPE_MTE1, PIPE_MTE2>(mte2DBFlag);
215	            TLOAD(aMatTile[mte2DBFlag], gmA);
216	            SetFlag<PIPE_MTE2, PIPE_MTE1>(0);
217	            TLOAD(bMatTile[mte2DBFlag], gmB);
218	        }
219	        SetFlag<PIPE_MTE2, PIPE_MTE1>(1);
220	        mte2DBFlag = (mte2DBFlag == 0) ? 1 : 0;
221	    }
222	
223	    const uint32_t currMte2Idx = (mte2DBFlag == 0) ? 1 : 0;     // mte2DBFlag reversed
224	    const uint32_t currMte2mxIdx = (mte2mxDBFlag == 0) ? 1 : 0; // mte2mxDBFlag reversed
225	
226	    MacroMatmul<
227	        baseK, baseScaleK, stepKa, stepKb, stepKscaleA, stepKscaleB, TileMatA, TileMatB, TileScaleA, TileScaleB,
228	        LeftTile, RightTile, LeftScaleTile, RightScaleTile, ResTile>(
229	        kIter, currMte2Idx, currMte2mxIdx, mte1DBFlag, aMatTile, bMatTile, aScaleMatTile, bScaleMatTile, aTile, bTile,
230	        aScaleTile, bScaleTile, cTile, currentM, currentN);
231	    mte1DBFlag = (mte1DBFlag == 0) ? 1 : 0;
232	}
233	
234	template <typename T, typename U, int m, int n, uint32_t singleCoreK, uint32_t baseM, uint32_t baseN, typename ResTile>
235	AICORE inline void StoreResult(
236	    ResTile& cTile, __gm__ T* currentDst, uint32_t i, uint32_t j, uint32_t currentM, uint32_t currentN)
237	{
238	    // TSTORE stage: write the finished C tile [baseM, baseN] back to GM.
239	    SetFlag<PIPE_M, PIPE_FIX>(0);
240	    WaitFlag<PIPE_M, PIPE_FIX>(0);
241	
242	    // the data size read from L0C after single k loop is [baseM, baseN]
243	    using DynShapeDim5 = Shape<1, 1, 1, -1, -1>;
244	    using DynStrideDim5 = pto::Stride<m * n, m * n, m * n, n, 1>;
245	    using GlobalDataOut = GlobalTensor<T, DynShapeDim5, DynStrideDim5, Layout::ND>;
246	
247	    uint32_t gmOffset = i * baseM * n + j * baseN;
248	    GlobalDataOut dstGlobal(currentDst + gmOffset, DynShapeDim5(currentM, currentN));
249	    TSTORE(dstGlobal, cTile);
250	
251	    SetFlag<PIPE_FIX, PIPE_M>(0);
252	    WaitFlag<PIPE_FIX, PIPE_M>(0);
253	}
254	
255	AICORE inline void InitSyncFlags()
256	{
257	    // supplement first sync instr for reverse sync in ProcessKIteration
258	    SetFlag<PIPE_MTE1, PIPE_MTE2>(0);
259	    SetFlag<PIPE_MTE1, PIPE_MTE2>(1);
260	    SetFlag<PIPE_M, PIPE_MTE1>(0);
261	    SetFlag<PIPE_M, PIPE_MTE1>(1);
262	}
263	
264	AICORE inline void WaitSyncFlags()
265	{
266	    // supplement last sync instr for reverse sync in ProcessKIteration
267	    WaitFlag<PIPE_M, PIPE_MTE1>(0);
268	    WaitFlag<PIPE_M, PIPE_MTE1>(1);
269	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(0);
270	    WaitFlag<PIPE_MTE1, PIPE_MTE2>(1);
271	}
272	
273	template <
274	    typename T, typename U, typename X, int m, int k, int n, uint32_t singleCoreM, uint32_t singleCoreK,
275	    uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t baseScaleK, uint32_t stepKa,
276	    uint32_t stepKb, uint32_t stepKscaleA, uint32_t stepKscaleB, typename TileMatA, typename TileMatB,
277	    typename TileScaleA, typename TileScaleB, typename LeftTile, typename RightTile, typename LeftScaleTile,
278	    typename RightScaleTile, typename ResTile>
279	AICORE inline void Compute(
280	    __gm__ U* currentSrc0, __gm__ U* currentSrc1, __gm__ X* currentSrc2, __gm__ X* currentSrc3, __gm__ T*& currentDst,
281	    TileMatA aMatTile[BUFFER_NUM], TileMatB bMatTile[BUFFER_NUM], TileScaleA aScaleMatTile[BUFFER_NUM],
282	    TileScaleB bScaleMatTile[BUFFER_NUM], LeftTile aTile[BUFFER_NUM], RightTile bTile[BUFFER_NUM],
283	    LeftScaleTile aScaleTile[BUFFER_NUM], RightScaleTile bScaleTile[BUFFER_NUM], ResTile& cTile,
284	    uint32_t currentSingleCoreM, uint32_t currentSingleCoreN)
285	{
286	    uint8_t mte2DBFlag = 0;
287	    uint8_t mte2mxDBFlag = 0;
288	    uint8_t mte1DBFlag = 0;
289	
290	    const uint32_t loopsM = (singleCoreM + baseM - 1) / baseM;
291	    const uint32_t loopsN = (singleCoreN + baseN - 1) / baseN;
292	    const uint32_t loopsK = (singleCoreK + baseK - 1) / baseK;
293	
294	    uint32_t remM = currentSingleCoreM % baseM;
295	    uint32_t remN = currentSingleCoreN % baseN;
296	
297	    for (uint32_t i = 0; i < loopsM; ++i) {
298	        for (uint32_t j = 0; j < loopsN; ++j) {
299	            uint32_t currentM = (i == loopsM - 1 && remM > 0) ? remM : baseM;
300	            uint32_t currentN = (j == loopsN - 1 && remN > 0) ? remN : baseN;
301	
302	            for (int buf = 0; buf < BUFFER_NUM; ++buf) {
303	                aMatTile[buf] = TileMatA(currentM, baseK * stepKa);
304	                bMatTile[buf] = TileMatB(baseK * stepKb, currentN);
305	                aScaleMatTile[buf] = TileScaleA(currentM, baseScaleK * stepKscaleA);
306	                bScaleMatTile[buf] = TileScaleB(baseScaleK * stepKscaleB, currentN);
307	
308	                aTile[buf] = LeftTile(currentM, baseK);
309	                bTile[buf] = RightTile(baseK, currentN);
310	                aScaleTile[buf] = LeftScaleTile(currentM, baseScaleK);
311	                bScaleTile[buf] = RightScaleTile(baseScaleK, currentN);
312	            }
313	
314	            ResTile outTile(currentM, currentN);
315	            TASSIGN(outTile, 0x0);
316	
317	            for (uint32_t kIter = 0; kIter < loopsK; ++kIter) {
318	                ProcessKIteration<
319	                    T, U, X, m, k, n, singleCoreK, baseM, baseK, baseN, baseScaleK, stepKa, stepKb, stepKscaleA,
320	                    stepKscaleB, TileMatA, TileMatB, TileScaleA, TileScaleB, LeftTile, RightTile, LeftScaleTile,
321	                    RightScaleTile, ResTile>(
322	                    kIter, i, j, currentSrc0, currentSrc1, currentSrc2, currentSrc3, aMatTile, bMatTile, aScaleMatTile,
323	                    bScaleMatTile, aTile, bTile, aScaleTile, bScaleTile, outTile, mte2DBFlag, mte2mxDBFlag, mte1DBFlag,
324	                    currentM, currentN);
325	            }
326	
327	            StoreResult<T, U, m, n, singleCoreK, baseM, baseN, ResTile>(outTile, currentDst, i, j, currentM, currentN);
328	        }
329	    }
330	}
331	
332	template <
333	    typename T, typename U, typename X, uint32_t blockDim, int m, int k, int n, uint32_t baseM, uint32_t baseK,
334	    uint32_t baseN, uint32_t stepM, uint32_t stepKa, uint32_t stepKb, uint32_t stepN, uint32_t singleCoreM,
335	    uint32_t singleCoreK, uint32_t singleCoreN>
336	AICORE inline void RunMxMatmulWithTail(
337	    __gm__ T* out, __gm__ U* src0, __gm__ U* src1, __gm__ X* src2, __gm__ X* src3, uint32_t validSingleCoreM,
338	    uint32_t validSingleCoreN)
339	{
340	    __gm__ U* currentSrc0 = nullptr;
341	    __gm__ U* currentSrc1 = nullptr;
342	    __gm__ X* currentSrc2 = nullptr;
343	    __gm__ X* currentSrc3 = nullptr;
344	    __gm__ T* currentDst = nullptr;
345	
346	    InitGMOffsets<T, U, X, m, k, n, singleCoreM, singleCoreK, singleCoreN>(
347	        currentSrc0, currentSrc1, currentSrc2, currentSrc3, currentDst, out, src0, src1, src2, src3, validSingleCoreM,
348	        validSingleCoreN);
349	
350	    constexpr uint32_t baseScaleK = baseK / SCALE_FACTOR;
351	    constexpr uint32_t stepKscaleA = stepKa * mxScalePara;
352	    constexpr uint32_t stepKscaleB = stepKb * mxScalePara;
353	
354	    // L1 Tile - use dynamic shape
355	    using TileMatA = Tile<TileType::Mat, U, baseM, baseK * stepKa, BLayout::ColMajor, -1, -1, SLayout::RowMajor>;
356	
357	    using TileMatB = Tile<TileType::Mat, U, baseK * stepKb, baseN, BLayout::RowMajor, -1, -1, SLayout::ColMajor>;
358	
359	    using TileScaleA =
360	        Tile<TileType::Mat, X, baseM, baseScaleK * stepKscaleA, BLayout::RowMajor, -1, -1, SLayout::RowMajor, 32>;
361	
362	    using TileScaleB =
363	        Tile<TileType::Mat, X, baseScaleK * stepKscaleB, baseN, BLayout::ColMajor, -1, -1, SLayout::ColMajor, 32>;
364	
365	    TileMatA aMatTile[BUFFER_NUM];
366	    TileMatB bMatTile[BUFFER_NUM];
367	    TileScaleA aScaleMatTile[BUFFER_NUM];
368	    TileScaleB bScaleMatTile[BUFFER_NUM];
369	    // L0 Tile - use dynamic shape
370	    using LeftTile = TileLeftCompact<U, baseM, baseK, -1, -1>;
371	    using RightTile = TileRightCompact<U, baseK, baseN, -1, -1>;
372	    using LeftScaleTile = TileLeftScaleCompact<X, baseM, baseScaleK, -1, -1>;
373	    using RightScaleTile = TileRightScaleCompact<X, baseScaleK, baseN, -1, -1>;
374	    using ResTile = TileAccCompact<float, baseM, baseN, -1, -1>;
375	
376	    LeftTile aTile[BUFFER_NUM];
377	    RightTile bTile[BUFFER_NUM];
378	    LeftScaleTile aScaleTile[BUFFER_NUM];
379	    RightScaleTile bScaleTile[BUFFER_NUM];
380	    ResTile cTile;
381	
382	    InitBuffers<
383	        T, U, X, baseM, baseK, baseN, baseScaleK, stepKa, stepKb, stepKscaleA, stepKscaleB, TileMatA, TileMatB,
384	        TileScaleA, TileScaleB, LeftTile, RightTile, LeftScaleTile, RightScaleTile, ResTile>(
385	        aMatTile, bMatTile, aScaleMatTile, bScaleMatTile, aTile, bTile, aScaleTile, bScaleTile, cTile);
386	
387	    InitSyncFlags();
388	    Compute<
389	        T, U, X, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, baseScaleK, stepKa, stepKb,
390	        stepKscaleA, stepKscaleB, TileMatA, TileMatB, TileScaleA, TileScaleB, LeftTile, RightTile, LeftScaleTile,
391	        RightScaleTile, ResTile>(
392	        currentSrc0, currentSrc1, currentSrc2, currentSrc3, currentDst, aMatTile, bMatTile, aScaleMatTile,
393	        bScaleMatTile, aTile, bTile, aScaleTile, bScaleTile, cTile, validSingleCoreM, validSingleCoreN);
394	
395	    WaitSyncFlags();
396	}
397	
398	template <
399	    typename T, typename U, typename X, uint32_t blockDim, int m, int k, int n, uint32_t singleCoreM,
400	    uint32_t singleCoreK, uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM,
401	    uint32_t stepKa, uint32_t stepKb, uint32_t stepN>
402	AICORE inline void RunMxMatmulDispatch(__gm__ T* out, __gm__ U* src0, __gm__ U* src1, __gm__ X* src2, __gm__ X* src3)
403	{
404	    constexpr uint32_t mIter = (m + singleCoreM - 1) / singleCoreM;
405	    constexpr uint32_t nIter = (n + singleCoreN - 1) / singleCoreN;
406	
407	    uint32_t coreIdx = get_block_idx();
408	
409	    if (coreIdx >= mIter * nIter) {
410	        return;
411	    }
412	
413	    const uint32_t mIterIdx = coreIdx % mIter;
414	    const uint32_t nIterIdx = coreIdx / mIter;
415	
416	    uint32_t currentSingleCoreM = singleCoreM;
417	    uint32_t currentSingleCoreN = singleCoreN;
418	
419	    if (mIterIdx == mIter - 1 && m % singleCoreM != 0) {
420	        currentSingleCoreM = m % singleCoreM;
421	    }
422	    if (nIterIdx == nIter - 1 && n % singleCoreN != 0) {
423	        currentSingleCoreN = n % singleCoreN;
424	    }
425	
426	    RunMxMatmulWithTail<
427	        T, U, X, blockDim, m, k, n, baseM, baseK, baseN, stepM, stepKa, stepKb, stepN, singleCoreM, singleCoreK,
428	        singleCoreN>(out, src0, src1, src2, src3, currentSingleCoreM, currentSingleCoreN);
429	}
430	
431	template <
432	    uint32_t blockDim, uint32_t m, uint32_t k, uint32_t n, uint32_t singleCoreM, uint32_t singleCoreK,
433	    uint32_t singleCoreN, uint32_t baseM, uint32_t baseK, uint32_t baseN, uint32_t stepM, uint32_t stepKa,
434	    uint32_t stepKb, uint32_t stepN>
435	__global__ AICORE void MxMatmulPerformance(
436	    __gm__ uint8_t* out, __gm__ uint8_t* src0, __gm__ uint8_t* src1, __gm__ uint8_t* src2, __gm__ uint8_t* src3)
437	{
438	    RunMxMatmulDispatch<
439	        bfloat16_t, float4_e2m1x2_t, float8_e8m0_t, blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM,
440	        baseK, baseN, stepM, stepKa, stepKb, stepN>(
441	        reinterpret_cast<__gm__ bfloat16_t*>(out), reinterpret_cast<__gm__ float4_e2m1x2_t*>(src0),
442	        reinterpret_cast<__gm__ float4_e2m1x2_t*>(src1), reinterpret_cast<__gm__ float8_e8m0_t*>(src2),
443	        reinterpret_cast<__gm__ float8_e8m0_t*>(src3));
444	}
445	
446	void LaunchMxMatmul(uint8_t* out, uint8_t* src0, uint8_t* src1, uint8_t* src2, uint8_t* src3, void* stream)
447	{
448	    constexpr uint32_t blockDim = 32;
449	    constexpr uint32_t m = 2040;
450	    constexpr uint32_t k = 8192;
451	    constexpr uint32_t n = 8100;
452	    constexpr uint32_t singleCoreM = 512;
453	    constexpr uint32_t singleCoreK = 8192;
454	    constexpr uint32_t singleCoreN = 1024;
455	    constexpr uint32_t baseM = 256;
456	    constexpr uint32_t baseK = 256;
457	    constexpr uint32_t baseN = 256;
458	    constexpr uint32_t stepM = 1;
459	    constexpr uint32_t stepKa = 2;
460	    constexpr uint32_t stepKb = 2;
461	    constexpr uint32_t stepN = 1;
462	    MxMatmulPerformance<
463	        blockDim, m, k, n, singleCoreM, singleCoreK, singleCoreN, baseM, baseK, baseN, stepM, stepKa, stepKb, stepN>
464	        <<<blockDim, nullptr, stream>>>(out, src0, src1, src2, src3);
465	}
466	
467	void LaunchMxMatmul(uint8_t* out, uint8_t* src0, uint8_t* src1, uint8_t* src2, uint8_t* src3, void* stream);
