144	    using CType = typename TileRes::DType;
145	    static_assert(std::is_same_v<CType, int32_t> || std::is_same_v<CType, float>, "Acc Type support int32_t or float.");
146	    if constexpr (std::is_same_v<CType, int32_t>) {
147	        static_assert(
148	            std::is_same_v<AType, int8_t> && std::is_same_v<BType, int8_t>,
149	            "Left Type and Right Type must be int8_t when Acc Type is int32_t.");
150	    } else if constexpr (std::is_same_v<CType, float>) {
151	        static_assert(
152	            (std::is_same_v<AType, half> && std::is_same_v<BType, half>) ||
153	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, bfloat16_t>) ||
154	                (std::is_same_v<AType, float> && std::is_same_v<BType, float>) ||
155	                (std::is_same_v<AType, float8_e4m3_t> && std::is_same_v<BType, float8_e4m3_t>) ||
