157	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e4m3_t>) ||
158	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e5m2_t>) ||
159	                (std::is_same_v<AType, hifloat8_t> && std::is_same_v<BType, hifloat8_t>),
160	            "No supported data type when Acc Type is float.");
