77	
78	    using MxShapeA = TileShape2D<ScaleType, M, kMX, Layout::MX_A_ZZ>;
79	    using MxStrideA = BaseShape2D<ScaleType, M, kMX, Layout::MX_A_ZZ>;
80	    using GlobalDataSrc2 = GlobalTensor<ScaleType, MxShapeA, MxStrideA, Layout::MX_A_ZZ>;
81	
82	    using MxShapeB = TileShape2D<ScaleType, kMX, N, Layout::MX_B_NN>;
83	    using MxStrideB = BaseShape2D<ScaleType, kMX, N, Layout::MX_B_NN>;
84	    using GlobalDataSrc3 = GlobalTensor<ScaleType, MxShapeB, MxStrideB, Layout::MX_B_NN>;
85	
86	    using GlobalDataSrc4 = GlobalTensor<
87	        BiasType, pto::Shape<1, 1, 1, 1, validN>, pto::Stride<1 * validN, 1 * validN, 1 * validN, validN, 1>>;
88	    using GlobalDataOut = GlobalTensor<
89	        OutType, pto::Shape<1, 1, 1, validM, validN>,
90	        pto::Stride<1 * validM * validN, 1 * validM * validN, validM * validN, validN, 1>>;
91	    GlobalDataSrc0 src0Global(src0);
92	    GlobalDataSrc1 src1Global(src1);
93	    GlobalDataSrc2 src2Global(src2);
94	    GlobalDataSrc3 src3Global(src3);
95	    GlobalDataSrc4 src4Global(src4);
96	    GlobalDataOut dstGlobal(out);
97	
98	    using TileMatAData =
99	        Tile<TileType::Mat, AType, M, kAlign, BLayout::ColMajor, validM, validK, SLayout::RowMajor, 512>;
100	    using TileMatBData =
101	        Tile<TileType::Mat, BType, kAlign, N, BLayout::ColMajor, validK, validN, SLayout::RowMajor, 512>;
102	
103	    using TileScaleAData =
104	        Tile<TileType::Mat, ScaleType, M, kMX, BLayout::RowMajor, validM, kMX, SLayout::RowMajor, 32>;
105	    using TileScaleBData =
106	        Tile<TileType::Mat, ScaleType, kMX, N, BLayout::ColMajor, kMX, validN, SLayout::ColMajor, 32>;
107	
108	    using TileBiasData = Tile<TileType::Mat, BiasType, 1, N, BLayout::RowMajor, 1, validN>;
109	
110	    using LeftTile = TileLeft<AType, M, kAlign, validM, validK>;
111	    using RightTile = TileRight<BType, kAlign, N, validK, validN>;
112	    using LeftScaleTile = TileLeftScale<ScaleType, M, kMX, validM, kMX>;
113	    using RightScaleTile = TileRightScale<ScaleType, kMX, N, kMX, validN>;
114	    using AccTile = TileAcc<OutType, M, N, validM, validN>;
115	    using BiasTile = Tile<TileType::Bias, OutType, 1, N, BLayout::RowMajor, 1, validN>;
116	
117	    TileMatAData aMatTile;
118	    TileMatBData bMatTile;
119	    TileScaleAData aScaleMatTile;
120	    TileScaleBData bScaleMatTile;
121	    TileBiasData biasDataTile;
122	    TASSIGN(aMatTile, 0x0);
123	    TASSIGN(bMatTile, M * kAlign);
124	    TASSIGN(aScaleMatTile, M * kAlign + kAlign * N);
125	    TASSIGN(bScaleMatTile, M * kAlign + kAlign * N + M * kMX);
126	    TASSIGN(biasDataTile, M * kAlign + kAlign * N + M * kMX + N * kMX);
127	
128	    LeftTile aTile;
129	    RightTile bTile;
130	    LeftScaleTile aScaleTile;
131	    RightScaleTile bScaleTile;
132	    AccTile cTile;
133	    BiasTile biasTile;
134	    TASSIGN(aTile, 0x0);
135	    TASSIGN(bTile, 0x0);
136	    TASSIGN(cTile, 0x0);
137	    TASSIGN(biasTile, 0x0);
138	
139	    uint64_t scaleAAddr = GetScaleAddr(aTile.data());
140	    uint64_t scaleBAddr = GetScaleAddr(bTile.data());
141	    TASSIGN(aScaleTile, scaleAAddr);
142	    TASSIGN(bScaleTile, scaleBAddr);
143	
144	    /*************************************TLOAD****************************************/
145	    TLOAD(aMatTile, src0Global);
146	    TLOAD(bMatTile, src1Global);
147	    // Clear L1 buffer
148	    // Tload will pad to 32B alignment with at most 32B padding
149	    if constexpr (kAlign - validK >= blockAlign) {
150	        TFILLPAD(aMatTile, aMatTile);
151	    }
152	    TFILLPAD(bMatTile, bMatTile);
153	
154	    TLOAD<TileScaleAData, GlobalDataSrc2>(aScaleMatTile, src2Global);
155	    TLOAD<TileScaleBData, GlobalDataSrc3>(bScaleMatTile, src3Global);
156	
157	    if constexpr (isBias) {
158	        TLOAD(biasDataTile, src4Global);
159	    }
160	
161	#ifndef __PTO_AUTO__
162	    set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
163	    wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
164	#endif
165	
166	    /**********************************TMOV && TEXTRACT**********************************/
167	    TMOV(aTile, aMatTile);
168	    TMOV(bTile, bMatTile);
169	
170	    TMOV(aScaleTile, aScaleMatTile);
171	    TMOV(bScaleTile, bScaleMatTile);
172	
173	#ifdef __PTO_AUTO__
174	    TGET_SCALE_ADDR(aScaleTile, aTile);
175	    TGET_SCALE_ADDR(bScaleTile, bTile);
176	#endif
177	
178	    if constexpr (isBias) {
179	        TMOV(biasTile, biasDataTile);
180	    }
181	
182	#ifndef __PTO_AUTO__
183	    set_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
184	    wait_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
185	#endif
186	
187	    /**********************************TMATMUL**********************************/
188	    if constexpr (isBias) {
189	        TMATMUL_MX(cTile, aTile, aScaleTile, bTile, bScaleTile, biasTile);
190	    } else {
191	        TMATMUL_MX(cTile, aTile, aScaleTile, bTile, bScaleTile);
192	    }
193	
194	#ifndef __PTO_AUTO__
195	    set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
196	    wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
197	#endif
198	
199	    /**********************************TSTORE**********************************/
200	    TSTORE(dstGlobal, cTile);
201	
202	    out = dstGlobal.data();
203	}
