205	template <
206	    typename OutType, typename AType, typename BType, typename ScaleType, typename BiasType, int validM, int validK,
207	    int validN, bool isBias, bool isFp4>
208	__global__ AICORE void RunTMATMULMX_SPLIT_K(
209	    __gm__ OutType* out, __gm__ AType* src0, __gm__ BType* src1, __gm__ ScaleType* src2, __gm__ ScaleType* src3,
210	    __gm__ BiasType* src4)
211	{
212	    constexpr int blockAlign = isFp4 ? 64 : 32; // need to be 32B aligned
213	
214	    constexpr int M = CeilAlign<int>(validM, 16);
215	    constexpr int K = CeilAlign<int>(validK, 64);
216	    constexpr int N = CeilAlign<int>(validN, blockAlign);
217	    constexpr int KMX = CeilDiv(K, 32);
218	
219	    constexpr int BASEK = 64;
220	    constexpr int BASEKMX = CeilDiv(BASEK, 32);
221	
222	    using GlobalDataSrc0 = GlobalTensor<
223	        AType, pto::Shape<1, 1, 1, validM, BASEK>,
224	        pto::Stride<1 * validM * validK, 1 * validM * validK, validM * validK, validK, 1>>;
225	    using GlobalDataSrc1 = GlobalTensor<
226	        BType, pto::Shape<1, 1, 1, BASEK, validN>,
227	        pto::Stride<1 * validK * validN, 1 * validK * validN, validK * validN, validN, 1>>;
228	
229	    using MxShapeA = TileShape2D<ScaleType, M, BASEKMX, Layout::MX_A_ZZ>;
230	    using MxStrideA = BaseShape2D<ScaleType, M, KMX, Layout::MX_A_ZZ>;
231	    using GlobalDataSrc2 = GlobalTensor<ScaleType, MxShapeA, MxStrideA, Layout::MX_A_ZZ>;
232	
233	    using MxShapeB = TileShape2D<ScaleType, BASEKMX, N, Layout::MX_B_NN>;
234	    using MxStrideB = BaseShape2D<ScaleType, KMX, N, Layout::MX_B_NN>;
235	    using GlobalDataSrc3 = GlobalTensor<ScaleType, MxShapeB, MxStrideB, Layout::MX_B_NN>;
236	
237	    using GlobalDataOut = GlobalTensor<
238	        OutType, pto::Shape<1, 1, 1, validM, validN>,
239	        pto::Stride<1 * validM * validN, 1 * validM * validN, validM * validN, validN, 1>>;
240	    GlobalDataOut dstGlobal(out);
241	
242	    using GlobalDataSrc4 = GlobalTensor<
243	        BiasType, pto::Shape<1, 1, 1, 1, validN>, pto::Stride<1 * validN, 1 * validN, 1 * validN, validN, 1>>;
244	    GlobalDataSrc4 src4Global(src4);
245	
246	    using TileMatAData = Tile<TileType::Mat, AType, M, BASEK, BLayout::ColMajor, validM, BASEK, SLayout::RowMajor, 512>;
247	    using TileMatBData = Tile<TileType::Mat, BType, BASEK, N, BLayout::ColMajor, BASEK, validN, SLayout::RowMajor, 512>;
248	
249	    using TileScaleAData =
250	        Tile<TileType::Mat, ScaleType, M, BASEKMX, BLayout::RowMajor, validM, BASEKMX, SLayout::RowMajor, 32>;
251	    using TileScaleBData =
252	        Tile<TileType::Mat, ScaleType, BASEKMX, N, BLayout::ColMajor, BASEKMX, validN, SLayout::ColMajor, 32>;
253	
254	    using TileBiasData = Tile<TileType::Mat, BiasType, 1, N, BLayout::RowMajor, 1, validN>;
255	
256	    using LeftTile = TileLeft<AType, M, BASEK, validM, BASEK>;
257	    using RightTile = TileRight<BType, BASEK, N, BASEK, validN>;
258	    using LeftScaleTile = TileLeftScale<ScaleType, M, BASEKMX, validM, BASEKMX>;
259	    using RightScaleTile = TileRightScale<ScaleType, BASEKMX, N, BASEKMX, validN>;
260	    using AccTile = TileAcc<OutType, M, N, validM, validN>;
261	    using BiasTile = Tile<TileType::Bias, BiasType, 1, N, BLayout::RowMajor, 1, validN>;
262	
263	    TileMatAData aMatTile;
264	    TileMatBData bMatTile;
265	    TileScaleAData aScaleMatTile;
266	    TileScaleBData bScaleMatTile;
267	    TileBiasData biasDataTile;
268	
269	    TASSIGN(aMatTile, 0x0);
270	    TASSIGN(bMatTile, M * BASEK);
271	    TASSIGN(aScaleMatTile, M * BASEK + N * BASEK);
272	    TASSIGN(bScaleMatTile, M * BASEK + N * BASEK + M * BASEKMX);
273	    TASSIGN(biasDataTile, M * BASEK + N * BASEK + M * BASEKMX + N * BASEKMX);
274	
275	    LeftTile aTile;
276	    RightTile bTile;
277	    AccTile cTile;
278	    LeftScaleTile aScaleTile;
279	    RightScaleTile bScaleTile;
280	    BiasTile biasTile;
281	
282	    TASSIGN(aTile, 0x0);
283	    TASSIGN(bTile, 0x0);
284	    TASSIGN(cTile, 0x0);
285	    TASSIGN(biasTile, 0x0);
286	
287	    uint64_t scaleAAddr = GetScaleAddr(aTile.data());
288	    uint64_t scaleBAddr = GetScaleAddr(bTile.data());
289	    TASSIGN(aScaleTile, scaleAAddr);
290	    TASSIGN(bScaleTile, scaleBAddr);
291	
292	    constexpr int iter = K / BASEK;
293	    for (int i = 0; i < iter; i++) {
294	        const int offsetA = (!isFp4) ? (i * BASEK) : (i * BASEK / 2);
295	        const int offsetB = (!isFp4) ? (validN * i * BASEK) : (validN * i * BASEK / 2);
296	        GlobalDataSrc0 src0Global(src0 + offsetA);
297	        GlobalDataSrc1 src1Global(src1 + offsetB);
298	
299	        /******************************TLOAD*****************************/
300	        TLOAD(aMatTile, src0Global);
301	        TLOAD(bMatTile, src1Global);
302	
303	        const int offsetAMX = i * BASEKMX * 16;
304	        const int offsetBMX = 16 * i * BASEKMX;
305	        GlobalDataSrc2 src2Global(src2 + offsetAMX);
306	        GlobalDataSrc3 src3Global(src3 + offsetBMX);
307	
308	        TLOAD<TileScaleAData, GlobalDataSrc2>(aScaleMatTile, src2Global);
309	        TLOAD<TileScaleBData, GlobalDataSrc3>(bScaleMatTile, src3Global);
310	
311	        if constexpr (isBias) {
312	            TLOAD(biasDataTile, src4Global);
313	        }
314	
315	#ifndef __PTO_AUTO__
316	        set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
317	        wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
318	#endif
319	
320	        /**************************TMOV && TEXTRACT**************************/
321	        TMOV(aTile, aMatTile);
322	        TMOV(bTile, bMatTile);
323	
324	        TMOV(aScaleTile, aScaleMatTile);
325	        TMOV(bScaleTile, bScaleMatTile);
326	
327	#ifdef __PTO_AUTO__
328	        TGET_SCALE_ADDR(aScaleTile, aTile);
329	        TGET_SCALE_ADDR(bScaleTile, bTile);
330	#endif
331	
332	        if constexpr (isBias) {
333	            TMOV(biasTile, biasDataTile);
334	        }
335	#ifndef __PTO_AUTO__
336	        set_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
337	        wait_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
338	#endif
339	
340	        if (i == 0) {
341	            if constexpr (isBias) {
342	                TMATMUL_MX(cTile, aTile, aScaleTile, bTile, bScaleTile, biasTile);
343	            } else {
344	                TMATMUL_MX(cTile, aTile, aScaleTile, bTile, bScaleTile);
345	            }
346	        } else {
347	            TMATMUL_MX(cTile, cTile, aTile, aScaleTile, bTile, bScaleTile);
348	        }
349	#ifndef __PTO_AUTO__
350	        set_flag(PIPE_M, PIPE_MTE2, EVENT_ID0);
351	        wait_flag(PIPE_M, PIPE_MTE2, EVENT_ID0);
352	#endif
353	    }
354	
355	#ifndef __PTO_AUTO__
356	    set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
357	    wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
358	#endif
359	    TSTORE(dstGlobal, cTile);
360	    out = dstGlobal.data();
361	}
