363	template <
364	    int format, typename OutType, typename AType, typename BType, typename ScaleType, int validM, int validK,
365	    int validN, bool isFp4>
366	__global__ AICORE void RunTGEMVMX(
367	    __gm__ OutType* out, __gm__ AType* src0, __gm__ BType* src1, __gm__ ScaleType* src2, __gm__ ScaleType* src3)
368	{
369	    constexpr int blockAlign = isFp4 ? 64 : 32; // need to be 32B aligned
370	
371	    constexpr int M = CeilAlign<int>(validM, 16);
372	    constexpr int kAlign = CeilAlign<int>(validK, 64);
373	    constexpr int N = CeilAlign<int>(validN, blockAlign);
374	
375	    constexpr uint8_t kMX = CeilDiv(kAlign, 32);
376	
377	    using GlobalDataSrc0 = GlobalTensor<
378	        AType, pto::Shape<1, 1, 1, validM, validK>,
379	        pto::Stride<1 * validM * validK, 1 * validM * validK, validM * validK, validK, 1>>;
380	    using GlobalDataSrc1 = GlobalTensor<
381	        BType, pto::Shape<1, 1, 1, validK, validN>,
382	        pto::Stride<1 * validK * validN, 1 * validK * validN, validK * validN, validN, 1>>;
383	    using GlobalDataSrc2 = GlobalTensor<ScaleType, pto::Shape<1, 1, 1, 1, kMX>, pto::Stride<kMX, kMX, kMX, kMX, 1>>;
384	
385	    using GlobalDataSrc3 = GlobalDataSrc3_t<ScaleType, format, kMX, validN>;
386	
387	    using GlobalDataOut = GlobalTensor<
388	        OutType, pto::Shape<1, 1, 1, validM, validN>,
389	        pto::Stride<1 * validM * validN, 1 * validM * validN, validM * validN, validN, 1>>;
390	
391	    GlobalDataSrc0 src0Global(src0);
392	    GlobalDataSrc1 src1Global(src1);
393	    GlobalDataSrc2 src2Global(src2);
394	    GlobalDataSrc3 src3Global(src3);
395	    GlobalDataOut dstGlobal(out);
396	
397	    constexpr int blockLeft = isFp4 ? 1024 : 512;
398	    constexpr int KLeft = CeilAlign<int>(validK, blockLeft);
399	    using TileMatAData = Tile<TileType::Mat, AType, 1, KLeft, BLayout::RowMajor, 1, validK>;
400	
401	    using TileScaleAData = Tile<TileType::Mat, ScaleType, 1, kMX, BLayout::RowMajor, 1, kMX, SLayout::RowMajor, 32>;
402	
403	    using TileMatBData =
404	        Tile<TileType::Mat, BType, kAlign, N, BLayout::ColMajor, validK, validN, SLayout::RowMajor, 512>;
405	    using TileScaleBData =
406	        Tile<TileType::Mat, ScaleType, kMX, N, BLayout::ColMajor, kMX, validN, SLayout::ColMajor, 32>;
407	
408	    using LeftTile = TileLeft<AType, 1, KLeft, 1, validK>;
409	    using RightTile = TileRightCompact<BType, kAlign, N, kAlign, validN>;
410	    using AccTile = TileAccCompact<OutType, M, N, validM, validN>;
411	
412	    using LeftScaleTile = TileLeftScaleCompact<ScaleType, 1, kMX, 1, kMX>;
413	    using RightScaleTile = TileRightScaleCompact<ScaleType, kMX, N, kMX, validN>;
414	
415	    TileMatAData aMatTile;
416	    TileMatBData bMatTile;
417	    TileScaleAData aScaleMatTile;
418	    TileScaleBData bScaleMatTile;
419	
420	    TASSIGN(aMatTile, 0x0);
421	    TASSIGN(bMatTile, 0x10000);
422	    TASSIGN(aScaleMatTile, 0x20000);
423	    TASSIGN(bScaleMatTile, 0x30000);
424	
425	    LeftTile aTile;
426	    RightTile bTile;
427	    LeftScaleTile aScaleTile;
428	    RightScaleTile bScaleTile;
429	    AccTile cTile;
430	
431	    TASSIGN(aTile, 0x0);
432	    TASSIGN(bTile, 0x0);
433	
434	    uint64_t scaleAAddr = GetScaleAddr(aTile.data());
435	    uint64_t scaleBAddr = GetScaleAddr(bTile.data());
436	    TASSIGN(aScaleTile, scaleAAddr);
437	    TASSIGN(bScaleTile, scaleBAddr);
438	
439	    TASSIGN(cTile, 0x0);
440	
441	    /*************************************TLOAD****************************************/
442	    TLOAD(aMatTile, src0Global);
443	    TLOAD(bMatTile, src1Global);
444	    TFILLPAD(bMatTile, bMatTile);
445	
446	    TLOAD<TileScaleAData, GlobalDataSrc2>(aScaleMatTile, src2Global);
447	    TLOAD<TileScaleBData, GlobalDataSrc3>(bScaleMatTile, src3Global);
448	
449	#ifndef __PTO_AUTO__
450	    set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
451	    wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
452	#endif
453	
454	    /**********************************TMOV && TEXTRACT**********************************/
455	
456	    TEXTRACT(aTile, aMatTile, 0, 0);
457	    TEXTRACT(bTile, bMatTile, 0, 0);
458	
459	    TMOV(aScaleTile, aScaleMatTile);
460	    TMOV(bScaleTile, bScaleMatTile);
461	
462	#ifdef __PTO_AUTO__
463	    TGET_SCALE_ADDR(aScaleTile, aTile);
464	    TGET_SCALE_ADDR(bScaleTile, bTile);
465	#endif
466	
467	#ifndef __PTO_AUTO__
468	    set_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
469	    wait_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
470	#endif
471	
472	    /**********************************TMATMUL**********************************/
473	
474	    TGEMV_MX(cTile, aTile, aScaleTile, bTile, bScaleTile);
475	
476	#ifndef __PTO_AUTO__
477	    set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
478	    wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
479	#endif
480	
481	    /**********************************TSTORE**********************************/
482	    TSTORE(dstGlobal, cTile);
483	
484	    out = dstGlobal.data();
485	}
