487	template <
488	    typename OutType, typename AType, typename BType, typename ScaleType, typename BiasType, int validM, int validK,
489	    int validN, bool isFp4>
490	__global__ AICORE void RunTGEMVMX_SPLIT_K(
491	    __gm__ OutType* out, __gm__ AType* src0, __gm__ BType* src1, __gm__ ScaleType* src2, __gm__ ScaleType* src3,
492	    __gm__ BiasType* src4)
493	{
494	    constexpr int blockAlign = isFp4 ? 64 : 32; // need to be 32B aligned
495	
496	    constexpr int M = CeilAlign<int>(validM, 16);
497	    constexpr int kAlign = CeilAlign<int>(validK, 64);
498	    constexpr int N = CeilAlign<int>(validN, blockAlign);
499	    constexpr int KMX = CeilDiv(kAlign, 32);
500	
501	    constexpr int BASEK = 1024;
502	    constexpr int BASEKMX = CeilDiv(BASEK, 32);
503	
504	    using GlobalDataSrc0 = GlobalTensor<
505	        AType, pto::Shape<1, 1, 1, validM, BASEK>,
506	        pto::Stride<1 * validM * validK, 1 * validM * validK, validM * validK, validK, 1>>;
507	    using GlobalDataSrc1 = GlobalTensor<
508	        BType, pto::Shape<1, 1, 1, BASEK, validN>,
509	        pto::Stride<1 * validK * validN, 1 * validK * validN, validK * validN, validN, 1>>;
510	    // SCALEA in GM, ND
511	    using GlobalDataSrc2 = GlobalTensor<ScaleType, pto::Shape<1, 1, 1, 1, BASEKMX>, pto::Stride<KMX, KMX, KMX, KMX, 1>>;
512	
513	    using MxShapeB = TileShape2D<ScaleType, BASEKMX, N, Layout::MX_B_NN>;
514	    using MxStrideB = BaseShape2D<ScaleType, KMX, N, Layout::MX_B_NN>;
515	    using GlobalDataSrc3 = GlobalTensor<ScaleType, MxShapeB, MxStrideB, Layout::MX_B_NN>;
516	
517	    using GlobalDataOut = GlobalTensor<
518	        OutType, pto::Shape<1, 1, 1, validM, validN>,
519	        pto::Stride<1 * validM * validN, 1 * validM * validN, validM * validN, validN, 1>>;
520	    GlobalDataOut dstGlobal(out);
521	
522	    using GlobalDataSrc4 = GlobalTensor<
523	        BiasType, pto::Shape<1, 1, 1, 1, validN>, pto::Stride<1 * validN, 1 * validN, 1 * validN, validN, 1>>;
524	    GlobalDataSrc4 src4Global(src4);
525	
526	    constexpr int blockLeft = isFp4 ? 1024 : 512;
527	    constexpr int KLeft = CeilAlign<int>(validK, blockLeft);
528	    using TileMatAData = Tile<TileType::Mat, AType, 1, BASEK, BLayout::RowMajor, 1, BASEK>;
529	
530	    // scale need 32B Align
531	    using TileScaleAData =
532	        Tile<TileType::Mat, ScaleType, 1, BASEKMX, BLayout::RowMajor, 1, BASEKMX, SLayout::RowMajor, 32>;
533	
534	    using TileMatBData = Tile<TileType::Mat, BType, BASEK, N, BLayout::ColMajor, BASEK, validN, SLayout::RowMajor, 512>;
535	    using TileScaleBData =
536	        Tile<TileType::Mat, ScaleType, BASEKMX, N, BLayout::ColMajor, BASEKMX, validN, SLayout::ColMajor, 32>;
537	    using TileBiasData = Tile<TileType::Mat, BiasType, 1, N, BLayout::RowMajor, 1, validN>;
538	
539	    using LeftTile = TileLeft<AType, 1, BASEK, 1, BASEK>;
540	    using RightTile = TileRightCompact<BType, BASEK, N, BASEK, validN>;
541	    using AccTile = TileAccCompact<OutType, M, N, validM, validN>;
542	    using LeftScaleTile = TileLeftScaleCompact<ScaleType, 1, BASEKMX, 1, BASEKMX>;
543	    using RightScaleTile = TileRightScaleCompact<ScaleType, BASEKMX, N, BASEKMX, validN>;
544	    using BiasTile = Tile<TileType::Bias, BiasType, 1, N, BLayout::RowMajor, 1, validN>;
545	
546	    TileMatAData aMatTile;
547	    TileMatBData bMatTile;
548	    TileScaleAData aScaleMatTile;
549	    TileScaleBData bScaleMatTile;
550	    TileBiasData biasDataTile;
551	    TASSIGN(aMatTile, 0x0);
552	    TASSIGN(bMatTile, 0x10000);
553	    TASSIGN(aScaleMatTile, 0x20000);
554	    TASSIGN(bScaleMatTile, 0x30000);
555	    TASSIGN(biasDataTile, 0x40000);
556	
557	    LeftTile aTile;
558	    RightTile bTile;
559	    LeftScaleTile aScaleTile;
560	    RightScaleTile bScaleTile;
561	    AccTile cTile;
562	    BiasTile biasTile;
563	
564	    TASSIGN(aTile, 0x0);
565	    TASSIGN(bTile, 0x0);
566	
567	#ifndef __PTO_AUTO__
568	    uint64_t scaleAAddr = GetScaleAddr(aTile.data());
569	    uint64_t scaleBAddr = GetScaleAddr(bTile.data());
570	    TASSIGN(aScaleTile, scaleAAddr);
571	    TASSIGN(bScaleTile, scaleBAddr);
572	#endif
573	
574	    TASSIGN(biasTile, 0x0);
575	    TASSIGN(cTile, 0x0);
576	
577	    constexpr int iter = CeilDiv(kAlign, BASEK);
578	    for (int i = 0; i < iter; i++) {
579	        const int offsetA = (!isFp4) ? (i * BASEK) : (i * BASEK / 2);
580	        const int offsetB = (!isFp4) ? (validN * i * BASEK) : (validN * i * BASEK / 2);
581	        GlobalDataSrc0 src0Global(src0 + offsetA);
582	        GlobalDataSrc1 src1Global(src1 + offsetB);
583	
584	        /*************************************TLOAD****************************************/
585	        TLOAD(aMatTile, src0Global);
586	        TLOAD(bMatTile, src1Global);
587	        const int offsetAMX = i * BASEKMX;
588	        const int offsetBMX = 16 * i * BASEKMX;
589	        GlobalDataSrc2 src2Global(src2 + offsetAMX);
590	        GlobalDataSrc3 src3Global(src3 + offsetBMX);
591	        TLOAD<TileScaleAData, GlobalDataSrc2>(aScaleMatTile, src2Global);
592	        TLOAD<TileScaleBData, GlobalDataSrc3>(bScaleMatTile, src3Global);
593	        if (i == 0) {
594	            TLOAD(biasDataTile, src4Global);
595	        }
596	#ifndef __PTO_AUTO__
597	        set_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
598	        wait_flag(PIPE_MTE2, PIPE_MTE1, EVENT_ID0);
599	#endif
600	
601	        /**********************************TMOV && TEXTRACT**********************************/
602	        TEXTRACT(aTile, aMatTile, 0, 0);
603	        TEXTRACT(bTile, bMatTile, 0, 0);
604	        TMOV(aScaleTile, aScaleMatTile);
605	        TMOV(bScaleTile, bScaleMatTile);
606	
607	#ifdef __PTO_AUTO__
608	        TGET_SCALE_ADDR(aScaleTile, aTile);
609	        TGET_SCALE_ADDR(bScaleTile, bTile);
610	#endif
611	
612	        if (i == 0) {
613	            TMOV(biasTile, biasDataTile);
614	        }
615	#ifndef __PTO_AUTO__
616	        set_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
617	        wait_flag(PIPE_MTE1, PIPE_M, EVENT_ID0);
618	#endif
619	        /**********************************TMATMUL**********************************/
620	        if (i == 0) {
621	            TGEMV_MX(cTile, aTile, aScaleTile, bTile, bScaleTile, biasTile);
622	        } else {
623	            TGEMV_MX(cTile, cTile, aTile, aScaleTile, bTile, bScaleTile);
624	        }
625	#ifndef __PTO_AUTO__
626	        set_flag(PIPE_M, PIPE_MTE2, EVENT_ID0);
627	        wait_flag(PIPE_M, PIPE_MTE2, EVENT_ID0);
628	#endif
629	    }
630	
631	#ifndef __PTO_AUTO__
632	    set_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
633	    wait_flag(PIPE_M, PIPE_FIX, EVENT_ID0);
634	#endif
635	    TSTORE(dstGlobal, cTile);
636	    out = dstGlobal.data();
637	}
