639	template <int32_t tilingKey>
640	void LaunchTMATMUL_MX(uint8_t* out, uint8_t* src0, uint8_t* src1, uint8_t* src2, uint8_t* src3, void* stream)
641	{
642	    if constexpr (tilingKey == 1) {
643	        RunTMATMULMX<float, float8_e5m2_t, float8_e5m2_t, float8_e8m0_t, float, 128, 64, 64, false, false>(
644	            reinterpret_cast<float*>(out), reinterpret_cast<float8_e5m2_t*>(src0),
645	            reinterpret_cast<float8_e5m2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
