669	            reinterpret_cast<float*>(out), reinterpret_cast<float4_e2m1x2_t*>(src0),
670	            reinterpret_cast<float4_e1m2x2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
671	            reinterpret_cast<float8_e8m0_t*>(src3), nullptr);
672	    } else if constexpr (tilingKey == 7) {
673	        RunTMATMULMX<float, float4_e2m1x2_t, float4_e1m2x2_t, float8_e8m0_t, float, 115, 64, 30, false, true>(
674	            reinterpret_cast<float*>(out), reinterpret_cast<float4_e2m1x2_t*>(src0),
675	            reinterpret_cast<float4_e1m2x2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
676	            reinterpret_cast<float8_e8m0_t*>(src3), nullptr);
677	    } else if constexpr (tilingKey == 8) {
678	        RunTMATMULMX<float, float8_e4m3_t, float8_e4m3_t, float8_e8m0_t, float, 16, 32, 16, false, false>(
679	            reinterpret_cast<float*>(out), reinterpret_cast<float8_e4m3_t*>(src0),
680	            reinterpret_cast<float8_e4m3_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
681	            reinterpret_cast<float8_e8m0_t*>(src3), nullptr);
682	    } else if constexpr (tilingKey == 9) {
683	        RunTMATMULMX<float, float8_e4m3_t, float8_e5m2_t, float8_e8m0_t, float, 10, 50, 54, false, false>(
684	            reinterpret_cast<float*>(out), reinterpret_cast<float8_e4m3_t*>(src0),
685	            reinterpret_cast<float8_e5m2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
686	            reinterpret_cast<float8_e8m0_t*>(src3), nullptr);
687	    } else if constexpr (tilingKey == 10) {
688	        RunTMATMULMX<float, float4_e2m1x2_t, float4_e2m1x2_t, float8_e8m0_t, float, 4, 30, 8, false, true>(
689	            reinterpret_cast<float*>(out), reinterpret_cast<float4_e2m1x2_t*>(src0),
690	            reinterpret_cast<float4_e2m1x2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
691	            reinterpret_cast<float8_e8m0_t*>(src3), nullptr);
692	    } else if constexpr (tilingKey == 11) {
693	        RunTGEMVMX<1, float, float4_e1m2x2_t, float4_e1m2x2_t, float8_e8m0_t, 1, 128, 62, true>(
694	            reinterpret_cast<float*>(out), reinterpret_cast<float4_e1m2x2_t*>(src0),
695	            reinterpret_cast<float4_e1m2x2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
696	            reinterpret_cast<float8_e8m0_t*>(src3));
697	    } else if constexpr (tilingKey == 12) {
698	        RunTGEMVMX<1, float, float8_e4m3_t, float8_e5m2_t, float8_e8m0_t, 1, 256, 20, true>(
699	            reinterpret_cast<float*>(out), reinterpret_cast<float8_e4m3_t*>(src0),
700	            reinterpret_cast<float8_e5m2_t*>(src1), reinterpret_cast<float8_e8m0_t*>(src2),
701	            reinterpret_cast<float8_e8m0_t*>(src3));
702	    }
