92	PTO_INTERNAL void CheckMadMxValid()
93	{
94	    using AType = typename TileLeft::DType;
95	    using BType = typename TileRight::DType;
96	    using CType = typename TileRes::DType;
97	    constexpr bool isFp8 = isSupportedFp8Combo<AType, BType>;
98	    constexpr bool isFp4 = isSupportedFp4Combo<AType, BType>;
99	    constexpr const int BASEK = 64;
100	
101	    static_assert((isFp4 || isFp8) && std::is_same_v<CType, float>, "TMatmulMX:No supported data type combination.");
102	    if constexpr (isFp4) {
103	        static_assert((TileLeft::Cols % 2 == 0), "TMatmulMX:For FP4 data types, aMatrixCol must be an even number.");
104	    }
105	    static_assert((TileLeft::Cols % BASEK == 0), "TMatmulMX: aMatrixCol must be a multiple of 64.");
106	    static_assert(
107	        ((TileLeft::Loc == TileType::Left) && (!TileLeft::isRowMajor) && (TileLeft::SFractal == SLayout::RowMajor)) &&
108	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
109	             (TileRight::SFractal == SLayout::ColMajor)) &&
110	            ((TileRes::Loc == TileType::Acc) && (!TileRes::isRowMajor) && (TileRes::SFractal == SLayout::RowMajor)),
111	        "TMatmulMX:Non-conforming matrix fractal");
